def top_model(usage):
    if len(usage) == 0:
        return None
    best = None
    best_total = -1
    for item in usage:
        total = 0
        for other in usage:
            if other['model'] == item['model']:
                total = total + other['tokens']
        if total > best_total:
            best_total = total
            best = item['model']
    return best

def top_model(usage):
    if not usage:
        return None
    totals = {}
    for row in usage:
        totals[row['model']] = totals.get(row['model'], 0) + row['token']
    return max(totals, key=totals.get)

